param([switch]$NoFetch)
$root = 'C:\Users\eric_rash\Desktop\DEV'
$skip = @('.claude','_tools','_DRIVE','token-dashboard')
$dirs = @()
foreach ($base in @($root, "$root\Football", "$root\SpecialRequests")) {
  if (-not (Test-Path $base)) { continue }
  Get-ChildItem $base -Directory -Force | Where-Object {
    $skip -notcontains $_.Name -and $_.Name -notlike '*_OLD_merged*' -and -not ($_.Attributes -band [IO.FileAttributes]::ReparsePoint)
  } | ForEach-Object { $dirs += $_.FullName }
}
$results = $dirs | ForEach-Object -ThrottleLimit 12 -Parallel {
  $d = $_
  $o = [ordered]@{ Path = $d; Name = (Split-Path $d -Leaf); Kind = ''; Remote = ''; Branch = ''; Dirty = 0; Ahead = ''; Behind = ''; Note = '' }
  if (-not (Test-Path (Join-Path $d '.git'))) { $o.Kind = 'not-repo'; return [pscustomobject]$o }
  $remote = git -C $d remote get-url origin 2>$null
  $o.Remote = $remote
  $o.Branch = git -C $d branch --show-current 2>$null
  $o.Dirty = (git -C $d status --porcelain 2>$null | Measure-Object).Count
  if (-not $remote) { $o.Kind = 'no-remote'; return [pscustomobject]$o }
  $o.Kind = if ($remote -match 'erash11') { 'erash11' } else { 'other-remote' }
  if (-not $using:NoFetch) { git -C $d fetch origin --quiet 2>$null; if ($LASTEXITCODE -ne 0) { $o.Note = 'fetch-failed' } }
  $up = "origin/$($o.Branch)"
  git -C $d rev-parse --verify --quiet $up *> $null
  if ($LASTEXITCODE -eq 0) {
    $counts = (git -C $d rev-list --left-right --count "HEAD...$up" 2>$null) -split '\s+'
    $o.Ahead = $counts[0]; $o.Behind = $counts[1]
  } else { $o.Note = ($o.Note + ' no-upstream-branch').Trim() }
  [pscustomobject]$o
}
$results | Export-Csv "$env:CLAUDE_JOB_DIR\tmp\inventory.csv" -NoTypeInformation -Encoding utf8
if (-not $env:CLAUDE_JOB_DIR) { $results | Export-Csv 'C:\Users\eric_rash\.claude\jobs\4aa3cb31\tmp\inventory.csv' -NoTypeInformation }
Write-Output ("total: " + $results.Count)
$results | Group-Object Kind | ForEach-Object { "{0}: {1}" -f $_.Name, $_.Count }
Write-Output '--- needs attention (dirty / ahead / behind / non-erash11 / notes)'
$results | Where-Object { $_.Kind -ne 'erash11' -or $_.Dirty -gt 0 -or ($_.Ahead -and $_.Ahead -ne '0') -or ($_.Behind -and $_.Behind -ne '0') -or $_.Note } |
  Sort-Object Kind, Name | Format-Table Name, Kind, Branch, Dirty, Ahead, Behind, Note, Path -AutoSize | Out-String -Width 260

